package de.local.garlicchat;

import android.Manifest;
import android.app.Activity;
import android.content.Intent;
import android.content.SharedPreferences;
import android.content.pm.PackageManager;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.media.AudioAttributes;
import android.speech.tts.UtteranceProgressListener;
import android.app.AlertDialog;
import android.os.Bundle;
import android.speech.RecognizerIntent;
import android.speech.SpeechRecognizer;
import android.speech.tts.TextToSpeech;
import android.view.Gravity;
import android.view.View;
import android.view.inputmethod.InputMethodManager;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MainActivity extends Activity {
    private final ExecutorService io = Executors.newSingleThreadExecutor();
    private SharedPreferences prefs;
    private LinearLayout root, messages;
    private EditText input, baseUrl, model, apiKey;
    private TextView status;
    private ScrollView scroll;
    private TextToSpeech tts;
    private boolean speakReplies = false;
    private boolean busy = false;
    private int profile = 0;
    private final String[] profiles = {"WLAN", "WireGuard", "Tailscale"};
    private String pref(String key, String fallback){return prefs.getString(key+profile, profile==0?prefs.getString(key,fallback):fallback);}
    private boolean ttsReady = false;
    private boolean reading = false;
    private int speechGeneration = 0;
    private final int ink=0xff25332d, green=0xff326b52, paper=0xfffaf9f5;
    private final JSONArray history = new JSONArray();
    private static final int SPEECH = 42, MIC_PERMISSION = 43;

    @Override public void onCreate(Bundle b) { super.onCreate(b); prefs=getSharedPreferences("garlic", MODE_PRIVATE); profile=Math.max(0,Math.min(2,prefs.getInt("profile",0))); speakReplies=prefs.getBoolean("speak",false); tts=new TextToSpeech(this, x -> runOnUiThread(()->{if(x==TextToSpeech.SUCCESS && tts!=null){ttsReady=tts.setLanguage(Locale.GERMANY)>=0;tts.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){} public void onDone(String id){runOnUiThread(()->{if(id.equals("last-"+speechGeneration))reading=false;});}public void onError(String id){runOnUiThread(()->{if(id.endsWith("-"+speechGeneration)){reading=false;Toast.makeText(MainActivity.this,"Sprachausgabe fehlgeschlagen",Toast.LENGTH_LONG).show();}});}});}})); showChat(); }
    private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);}
    private TextView text(String s,int size){ TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(ink);return t; }
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private void pad(View v,int p){v.setPadding(dp(p),dp(p),dp(p),dp(p));}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(ink);b.setTextSize(14);b.setMinHeight(dp(48));b.setMinimumHeight(dp(48));b.setBackground(shape(0xffe8eee8,24));pad(b,12);return b;}
    private void accent(Button b){b.setBackground(shape(green,24));b.setTextColor(-1);}
    private void base(String title){root=column();root.setBackgroundColor(paper);setContentView(root);LinearLayout top=row();pad(top,12);ImageView logo=new ImageView(this);logo.setImageResource(de.local.garlicchat.R.drawable.onion);top.addView(logo,new LinearLayout.LayoutParams(dp(40),dp(40)));TextView h=text(title,21);h.setTypeface(null,Typeface.BOLD);pad(h,8);top.addView(h,new LinearLayout.LayoutParams(0,-2,1));Button settings=btn("⚙");settings.setContentDescription("Einstellungen");top.addView(settings);settings.setOnClickListener(v->{if(!busy)showSettings();});root.addView(top);}
    private void showChat(){base("Garlic Chat");LinearLayout controls=row();pad(controls,12);Spinner selector=new Spinner(this);selector.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,profiles));selector.setSelection(profile);controls.addView(selector,new LinearLayout.LayoutParams(0,dp(48),1));Button clear=btn("+ Neuer Chat");controls.addView(clear);clear.setOnClickListener(v->{if(busy)return;new AlertDialog.Builder(this).setTitle("Neuer Chat?").setMessage("Der aktuelle Verlauf wird gelöscht.").setNegativeButton("Abbrechen",null).setPositiveButton("Neuer Chat",(d,w)->{stopSpeech();while(history.length()>0)history.remove(0);saveHistory();showChat();}).show();});root.addView(controls);selector.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(pos==profile)return;if(busy){selector.setSelection(profile);return;}profile=pos;prefs.edit().putInt("profile",profile).apply();showChat();}});status=text("Server wird geprüft …",12);status.setPadding(dp(18),0,dp(18),dp(8));root.addView(status);scroll=new ScrollView(this);scroll.setFillViewport(true);messages=column();pad(messages,16);scroll.addView(messages);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));loadHistory();if(history.length()==0){TextView welcome=text("Wie kann ich dir helfen?",25);welcome.setTypeface(null,Typeface.BOLD);welcome.setGravity(Gravity.CENTER);pad(welcome,24);messages.addView(welcome);TextView sub=text("Dein persönlicher KI-Assistent auf der PS4 Pro",15);sub.setGravity(Gravity.CENTER);messages.addView(sub);}
    LinearLayout composer=column();pad(composer,12);LinearLayout bar=row();bar.setBackground(shape(0xffe9eee9,26));pad(bar,6);input=new EditText(this);input.setTextColor(ink);input.setTextSize(16);input.setBackgroundColor(android.graphics.Color.TRANSPARENT);input.setMinLines(1);input.setMaxLines(5);input.setHint("Frag Garlic …");pad(input,10);bar.addView(input,new LinearLayout.LayoutParams(0,-2,1));Button mic=btn("🎙");mic.setContentDescription("Nachricht diktieren");bar.addView(mic);mic.setOnClickListener(v->startSpeech());Button send=btn("↑");accent(send);send.setContentDescription("Nachricht senden");bar.addView(send);send.setOnClickListener(v->sendMessage());composer.addView(bar);LinearLayout bottom=row();Switch voice=new Switch(this);voice.setText("Antworten vorlesen");voice.setTextColor(ink);voice.setChecked(speakReplies);bottom.addView(voice,new LinearLayout.LayoutParams(0,dp(48),1));voice.setOnCheckedChangeListener((v,on)->{speakReplies=on;prefs.edit().putBoolean("speak",on).apply();if(!on)stopSpeech();});Button stop=btn("■ Stopp");bottom.addView(stop);stop.setOnClickListener(v->stopSpeech());composer.addView(bottom);root.addView(composer);testConnection();}
    private void addMessage(String role,String body){boolean user=role.equals("user");LinearLayout card=column();card.setBackground(shape(user?0xffdce9df:0xffffffff,20));pad(card,16);TextView who=text(user?"Du":"Garlic",12);who.setTypeface(null,Typeface.BOLD);card.addView(who);TextView content=text(body,16);content.setLineSpacing(dp(4),1.05f);content.setTextIsSelectable(true);card.addView(content);if(!user){LinearLayout actions=row();Button read=btn("▶ Vorlesen");actions.addView(read);read.setOnClickListener(v->speakText(body));Button copy=btn("Kopieren");actions.addView(copy);copy.setOnClickListener(v->{android.content.ClipboardManager cb=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cb.setPrimaryClip(android.content.ClipData.newPlainText("Garlic",body));Toast.makeText(this,"Kopiert",Toast.LENGTH_SHORT).show();});card.addView(actions);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);if(user)lp.leftMargin=dp(38);else lp.rightMargin=dp(8);messages.addView(card,lp);scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));}
    private void stopSpeech(){speechGeneration++;reading=false;if(tts!=null)tts.stop();}
    private void speakText(String body){if(!ttsReady||tts==null){new AlertDialog.Builder(this).setTitle("Sprachausgabe nicht verfügbar").setMessage("Bitte installiere oder aktiviere eine deutsche Stimme in den Android-Einstellungen für Text-in-Sprache und starte Garlic Chat neu.").setPositiveButton("OK",null).show();return;}stopSpeech();reading=true;int gen=speechGeneration;int limit=Math.min(3000,TextToSpeech.getMaxSpeechInputLength());for(int start=0;start<body.length();){int end=Math.min(body.length(),start+limit);if(end<body.length()){int space=body.lastIndexOf(' ',end);if(space>start)end=space;else if(Character.isHighSurrogate(body.charAt(end-1)))end--;}String id=(end==body.length()?"last":"part"+start)+"-"+gen;int result=tts.speak(body.substring(start,end),TextToSpeech.QUEUE_ADD,null,id);if(result==TextToSpeech.ERROR){stopSpeech();Toast.makeText(this,"Sprachausgabe konnte nicht gestartet werden",Toast.LENGTH_LONG).show();return;}start=end;}}
    private String base(){String s=pref("url",profile==0?"http://192.168.1.5:8080/v1":prefs.getString("url0",prefs.getString("url","http://192.168.1.5:8080/v1"))).trim();while(s.endsWith("/"))s=s.substring(0,s.length()-1);return s;}
    private JSONObject request(String path,JSONObject body)throws Exception{URL u=new URL(base()+path);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(8000);c.setReadTimeout(600000);c.setRequestProperty("Accept","application/json");String key=pref("key","");if(!key.isEmpty())c.setRequestProperty("Authorization","Bearer "+key);if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();InputStream is=code<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=is.read(buf))!=-1)out.write(buf,0,n);String result=out.toString("UTF-8");c.disconnect();if(code<200||code>=300)throw new IOException("HTTP "+code+": "+result);return new JSONObject(result);}
    private void testConnection(){final TextView target=status; final int selected=profile; io.execute(()->{try{JSONObject r=request("/models",null);runOnUiThread(()->{if(status==target&&profile==selected&&!busy)target.setText("Verbunden · "+profiles[selected]);});}catch(Exception e){runOnUiThread(()->{if(status==target&&profile==selected&&!busy)target.setText("Nicht verbunden · "+e.getMessage());});}});}
    private void sendMessage(){if(busy)return;String q=input.getText().toString().trim();if(q.isEmpty())return;busy=true;if(history.length()==0)messages.removeAllViews();input.setText("");((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);addMessage("user",q);try{history.put(new JSONObject().put("role","user").put("content",q));}catch(Exception ignored){}saveHistory();status.setText("Garlic LLM antwortet …");io.execute(()->{try{JSONArray msgs=new JSONArray();msgs.put(new JSONObject().put("role","system").put("content","Du bist ein hilfreicher Assistent. Antworte auf Deutsch, sofern der Nutzer keine andere Sprache verwendet."));for(int i=0;i<history.length();i++)msgs.put(history.getJSONObject(i));JSONObject req=new JSONObject().put("messages",msgs).put("max_tokens",1024).put("stream",false);String m=pref("model","").trim();if(m.isEmpty()){JSONArray models=request("/models",null).optJSONArray("data");if(models!=null&&models.length()>0)m=models.getJSONObject(0).optString("id","");}if(!m.isEmpty())req.put("model",m);JSONObject res=request("/chat/completions",req);String answer=res.getJSONArray("choices").getJSONObject(0).getJSONObject("message").optString("content","");if(answer.isEmpty())answer="(Leere Antwort vom Server)";final String a=answer;runOnUiThread(()->{busy=false;try{history.put(new JSONObject().put("role","assistant").put("content",a));}catch(JSONException ignored){}saveHistory();addMessage("assistant",a);status.setText("Bereit");if(speakReplies)speakText(a);});}catch(Exception e){runOnUiThread(()->{busy=false;history.remove(history.length()-1);saveHistory();showChat();input.setText(q);status.setText("Fehler: "+e.getMessage());});}});}
    private void showSettings(){base("Profil: "+profiles[profile]);pad(root,16);root.addView(text("Garlic LLM – OpenAI-kompatible API",16));baseUrl=field("Serveradresse, z. B. http://192.168.1.5:8080/v1",base());model=field("Modell-ID (optional; leer = Serverstandard)",pref("model",""));apiKey=field("API-Key (optional)",pref("key",""));apiKey.setInputType( android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);root.addView(baseUrl);root.addView(model);root.addView(apiKey);TextView note=text("WLAN: lokale PS4-IP. WireGuard: Tunnel in Android aktivieren und lokale PS4-IP nutzen. Tailscale: Subnet-Router und freigegebene Route oder erreichbaren Proxy nutzen. HTTP ist außerhalb eines VPN unverschlüsselt.",13);pad(note,12);root.addView(note);Button save=btn("Speichern & verbinden");root.addView(save);save.setOnClickListener(v->{String u=baseUrl.getText().toString().trim();if(!validUrl(u)){Toast.makeText(this,"Adresse muss mit http:// oder https:// beginnen",Toast.LENGTH_LONG).show();return;}prefs.edit().putString("url"+profile,u).putString("model"+profile,model.getText().toString().trim()).putString("key"+profile,apiKey.getText().toString().trim()).apply();showChat();});Button back=btn("Zurück zum Chat");root.addView(back);back.setOnClickListener(v->showChat()); }
    private boolean validUrl(String value){try{URI u=new URI(value);return ("http".equals(u.getScheme())||"https".equals(u.getScheme()))&&u.getHost()!=null&&u.getUserInfo()==null&&u.getQuery()==null&&u.getFragment()==null;}catch(Exception e){return false;}}
    private EditText field(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setSingleLine(true);return e;}
    private void startSpeech(){if(busy)return;if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},MIC_PERMISSION);return;}if(!SpeechRecognizer.isRecognitionAvailable(this)){Toast.makeText(this,"Spracherkennung auf diesem Gerät nicht verfügbar",Toast.LENGTH_LONG).show();return;}Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"de-DE");i.putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE,true);i.putExtra(RecognizerIntent.EXTRA_PROMPT,"Jetzt sprechen");try{startActivityForResult(i,SPEECH);}catch(Exception e){Toast.makeText(this,"Spracherkennung konnte nicht gestartet werden",Toast.LENGTH_LONG).show();}}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==SPEECH&&result==RESULT_OK&&data!=null){ArrayList<String> r=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(r!=null&&!r.isEmpty())input.setText((input.getText()+" "+r.get(0)).trim());}}
    @Override public void onRequestPermissionsResult(int req,String[] p,int[] g){super.onRequestPermissionsResult(req,p,g);if(req==MIC_PERMISSION&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startSpeech();}
    private void saveHistory(){prefs.edit().putString("history",history.toString()).apply();}
    private void loadHistory(){while(history.length()>0)history.remove(0);try{JSONArray saved=new JSONArray(prefs.getString("history","[]"));for(int i=0;i<saved.length();i++){JSONObject m=saved.getJSONObject(i);history.put(m);addMessage(m.optString("role"),m.optString("content"));}}catch(Exception ignored){}}
    @Override protected void onDestroy(){if(tts!=null)tts.shutdown();io.shutdown();super.onDestroy();}
}
